import { useEffect, useState } from "react";
import { Database } from "lucide-react";
import { getAuthToken, removeAuthToken } from "../../api/auth";

export default function AppHeader({ onLoginClick }) {
  const [isLoggedIn, setIsLoggedIn] = useState(!!getAuthToken());

  useEffect(() => {
    const handleStorage = () => setIsLoggedIn(!!getAuthToken());
    window.addEventListener("storage", handleStorage);
    return () => window.removeEventListener("storage", handleStorage);
  }, []);

  function handleLogout() {
    removeAuthToken();
    setIsLoggedIn(false);
    if (typeof onLoginClick === "function") {
      // ensure parent can respond if it expects a callback
      try {
        onLoginClick(false);
      } catch {}
    }
  }

  return (
    <div className="header">
      <div className="header-brand">
        <div className="header-icon">
          <Database size={22} />
        </div>
        <div>
          <h2>AutoPrepAI</h2>
          <p>AI-Powered Data Cleaning & Preparation</p>
        </div>
      </div>

      {!isLoggedIn ? (
        <button onClick={onLoginClick}>Login</button>
      ) : (
        <button onClick={handleLogout}>Logout</button>
      )}
    </div>
  );
}
